insert into site_config(key, value, updated_at) values ('banner_rotator', '{"enabled":true,"bg":"#2E6E6A","messages":[{"tr":"Noktalama tek başına anlamı tersine çevirir: \"Let''s eat, Grandma\" ile \"Let''s eat Grandma\" aynı değildir.","en":"Punctuation alone flips meaning: \"Let''s eat, Grandma\" is not \"Let''s eat Grandma.\"","link":"https://gringlizce.com/konu-anlatimi"},{"tr":"İngilizcede sıfat sırası sabittir: \"big red car\" doğru, \"red big car\" kulağı tırmalar (görüş-boyut-yaş-renk...).","en":"English fixes adjective order: \"big red car\" is right, \"red big car\" sounds off (opinion-size-age-color...).","link":"https://gringlizce.com/gramer-adjective-order"},{"tr":"Shakespeare İngilizceye 1700''den fazla sözcük kazandırdı — \"lonely\", \"eyeball\", \"fashionable\" onlardan.","en":"Shakespeare gave English over 1,700 words — \"lonely,\" \"eyeball,\" and \"fashionable\" among them.","link":"https://gringlizce.com/blog"},{"tr":"\"ghoti\" aslında \"fish\" gibi okunabilir: enou**gh**, w**o**men, na**ti**on. İngilizce yazımı kuralsız görünür ama örüntülüdür.","en":"\"ghoti\" could spell \"fish\": enou**gh**, w**o**men, na**ti**on. English spelling looks lawless but has patterns.","link":"https://gringlizce.com/telaffuz-word-stress"},{"tr":"\"literally\" sözlüklerde artık mecazi anlamıyla da yer alıyor — dil kurallarla değil kullanımla yaşar.","en":"Dictionaries now list \"literally\" in its figurative sense too — usage, not rules, keeps a language alive.","link":"https://gringlizce.com/konu-anlatimi"},{"tr":"En çok karıştırılan ikili: \"affect\" fiildir (etkilemek), \"effect\" isimdir (etki). Tek harf, iki dünya.","en":"The classic mix-up: \"affect\" is the verb, \"effect\" the noun. One letter, two worlds.","link":"https://gringlizce.com/gramer-linking-words"},{"tr":"İngilizce tek büyük dildir ki \"I\" zamirini her zaman büyük harfle yazar.","en":"English is the only major language that always capitalizes the pronoun \"I.\"","link":"https://gringlizce.com/konu-anlatimi"},{"tr":"\"rhythm\" ve \"rhythms\" — sesli harf içermeyen en uzun yaygın İngilizce sözcükler.","en":"\"rhythm\" and \"rhythms\" are among the longest common English words with no vowel letters.","link":"https://gringlizce.com/kelime"},{"tr":"İngilizcenin resmi bir dil akademisi yoktur; sözlükler kuralı koymaz, kullanımı KAYDEDER.","en":"English has no official language academy; dictionaries don''t set rules, they record usage.","link":"https://gringlizce.com/konu-anlatimi"},{"tr":"Bir cümlede sözcük sırasını değiştirmek vurguyu değiştirir: \"Only she loves him\" ile \"She loves only him\" farklıdır.","en":"Word order shifts emphasis: \"Only she loves him\" differs from \"She loves only him.\"","link":"https://gringlizce.com/gramer-inversion"},{"tr":"\"Uncopyrightable\" 15 harflidir ve hiçbir harfi tekrar etmez — İngilizcenin en uzun yaygın izogramlarından.","en":"\"Uncopyrightable\" has 15 letters and repeats none — one of English''s longest common isograms.","link":"https://gringlizce.com/kelime"},{"tr":"Sessiz harfler İngilizce sözcüklerin çoğunda vardır; \"knight\" altı harf, üç ses.","en":"Silent letters hide in most English words: \"knight\" is six letters but three sounds.","link":"https://gringlizce.com/telaffuz-minimal-pairs"},{"tr":"Digital SAT uyarlanır: ilk R&W modülünde iyi gidersen ikincisi zorlaşır ve en yüksek puan bandı ancak öyle açılır.","en":"The Digital SAT adapts: do well on module 1 and module 2 gets harder — that''s the only path to the top score band.","link":"https://gringlizce.com/sat-soru-bankasi"},{"tr":"SAT dilbilgisinde \"NO CHANGE\" şıkkı diğerleri kadar sık doğrudur; refleksle eleme.","en":"On SAT grammar, \"NO CHANGE\" is correct about as often as any other option — don''t reflexively rule it out.","link":"https://gringlizce.com/sat-soru-bankasi"},{"tr":"IELTS Reading''de cevaplar metinde neredeyse hep SIRAYLA gelir; 5. sorunun cevabı 4''ünkinden sonradır.","en":"IELTS Reading answers almost always appear in passage order — question 5''s answer comes after question 4''s.","link":"https://gringlizce.com/ielts-soru-bankasi"},{"tr":"IELTS''te en sık puan kaybı parlak dilde değil, görevi tam karşılamamakta (Task Response) olur.","en":"The most common IELTS band loss isn''t weak language — it''s not fully answering the task.","link":"https://gringlizce.com/ielts-ornek-sorular"},{"tr":"TOEFL Speaking''de ezber şablon fazla belli olursa puan düşer; içerik ve doğallık kazandırır.","en":"On TOEFL Speaking, an obvious memorized template lowers your score — content and naturalness win.","link":"https://gringlizce.com/toefl-soru-bankasi"},{"tr":"YDS''de her soru eşit puandır; uzun paragrafta takılmak yerine kolayları toplayıp sona dönmek daha çok net getirir.","en":"Every YDS question is worth the same — bank the easy ones and return to long passages for more net correct.","link":"https://gringlizce.com/yds-soru-bankasi"},{"tr":"SAT Math''te en çok puan, zor soruda değil, kolay soruda yapılan dikkatsiz hatanın önlenmesinde saklıdır.","en":"On SAT Math, the biggest gains come from not fumbling easy questions, not from cracking the hardest one.","link":"https://gringlizce.com/sat-soru-bankasi"},{"tr":"Çeldirici uzun ve ayrıntılı diye doğru değildir; iyi yazılmış sınavda uzunluk ipucu vermez, kanıt verir.","en":"A long, detailed option isn''t the answer; in a well-built test, length is no clue — evidence is.","link":"https://gringlizce.com/sat-soru-bankasi"},{"tr":"Okuma sorusunda \"kısmen doğru\" şık en tehlikeli tuzaktır: bir kelimesi metinle çelişir.","en":"In reading questions the \"partly true\" option is the deadliest trap — one word contradicts the text.","link":"https://gringlizce.com/sat-soru-bankasi"},{"tr":"Bir kelimeyi kalıcı kılmak için onu birçok farklı bağlamda görmen gerekir; izole liste hızla silinir.","en":"To make a word stick you must meet it in many contexts — an isolated list fades fast.","link":"https://gringlizce.com/kelime"},{"tr":"Yanlış çözdüğün soruyu bir gün sonra tekrar çöz: hafıza, tam unutmaya başladığında tekrar edince pekişir.","en":"Redo a missed question a day later — memory consolidates when you review just as forgetting begins.","link":"https://gringlizce.com/ogrenme-haritasi"},{"tr":"Deneme çözmek fotoğraf çeker; hata analizi ilerleme sağlar. Asıl çalışma denemeden SONRA başlar.","en":"A mock test takes a snapshot; reviewing mistakes creates progress. The real work starts after the test.","link":"https://gringlizce.com/sat-deneme"},{"tr":"Her gün 20 dakika, haftada bir 3 saatlik maratondan daha çok öğretir — süreklilik yoğunluğu yener.","en":"Twenty minutes daily teaches more than one three-hour weekend cram — consistency beats intensity.","link":"https://gringlizce.com/ogrenme-haritasi"},{"tr":"Konuyu okuduktan hemen sonra o konudan 5 soru çöz; öğrenmeyi teste bağlamak bilgiyi kilitler.","en":"Right after reading a topic, do 5 questions on it — linking learning to testing locks it in.","link":"https://gringlizce.com/konu-anlatimi"},{"tr":"Sesli okumak telaffuz ve akıcılığı aynı anda geliştirir; beyin duyduğu sesi daha iyi hatırlar.","en":"Reading aloud builds pronunciation and fluency at once — the brain remembers what it hears.","link":"https://gringlizce.com/telaffuz-connected-speech"},{"tr":"Akademik yazıda \"very + sıfat\" yerine tek güçlü sözcük kullan: \"very important\" yerine \"crucial\".","en":"In academic writing, swap \"very + adjective\" for one strong word: \"very important\" becomes \"crucial.\"","link":"https://gringlizce.com/akademik-boosters"},{"tr":"İyi akademik cümle iddiayı yumuşatır: \"X causes Y\" yerine \"X is likely to contribute to Y\" (hedging).","en":"Strong academic writing hedges: not \"X causes Y\" but \"X is likely to contribute to Y.\"","link":"https://gringlizce.com/akademik-hedging"},{"tr":"Bağlaçlar fikirler arası köprüdür: \"however\", \"therefore\", \"nevertheless\" cümleye yön verir.","en":"Connectors bridge ideas: \"however,\" \"therefore,\" and \"nevertheless\" steer the reader.","link":"https://gringlizce.com/akademik-cohesion-coherence"},{"tr":"Nominalizasyon akademik tona yükseltir: \"they decided\" yerine \"their decision\".","en":"Nominalization lifts the academic tone: \"they decided\" becomes \"their decision.\"","link":"https://gringlizce.com/akademik-nominalization"},{"tr":"Kısa, net cümle uzun ve dolambaçlıdan güçlüdür; virgülle uzatmak zekâ değil risk taşır.","en":"A short, clear sentence beats a long, tangled one — stacking commas is risk, not sophistication.","link":"https://gringlizce.com/yazi-pratigi"},{"tr":"Paraphrase, IELTS ve TOEFL''ın gizli belkemiğidir: aynı fikri farklı sözcükler ve yapıyla kur.","en":"Paraphrasing is the quiet backbone of IELTS and TOEFL — same idea, new words and structure.","link":"https://gringlizce.com/akademik-paraphrasing"},{"tr":"IELTS yazıda dört paragraf yeter, asla beş: giriş, iki gelişme, sonuç. Fazlası zamanı yer.","en":"Four paragraphs is enough for IELTS writing, never five: intro, two bodies, conclusion.","link":"https://gringlizce.com/ielts-ornek-sorular"},{"tr":"\"nuance\" — ince anlam farkı; akademik düşüncenin kalbi. \"a subtle nuance in tone\".","en":"\"nuance\" — a subtle difference in meaning; the heart of academic thinking.","link":"https://gringlizce.com/kelime"},{"tr":"\"mitigate\" — bir etkiyi hafifletmek. \"measures to mitigate the risk\".","en":"\"mitigate\" — to make something less severe: \"measures to mitigate the risk.\"","link":"https://gringlizce.com/kelime"},{"tr":"\"ubiquitous\" — her yerde bulunan. \"Smartphones are now ubiquitous.\"","en":"\"ubiquitous\" — found everywhere: \"Smartphones are now ubiquitous.\"","link":"https://gringlizce.com/kelime"},{"tr":"\"juxtapose\" — karşıtlığı görünür kılmak için yan yana koymak.","en":"\"juxtapose\" — to place side by side so a contrast stands out.","link":"https://gringlizce.com/kelime"},{"tr":"\"undermine\" — bir şeyi yavaşça, içten zayıflatmak. \"doubts that undermine trust\".","en":"\"undermine\" — to weaken something gradually from within.","link":"https://gringlizce.com/kelime"},{"tr":"\"compelling\" — karşı konulmaz derecede ikna edici. \"a compelling argument\".","en":"\"compelling\" — convincing in a way that''s hard to resist.","link":"https://gringlizce.com/kelime"},{"tr":"\"scrutinize\" — en ince ayrıntısına dek incelemek.","en":"\"scrutinize\" — to examine in the closest detail.","link":"https://gringlizce.com/kelime"},{"tr":"\"inevitable\" — kaçınılmaz, önlenemez. Sonuç cümlelerinin gücü.","en":"\"inevitable\" — certain to happen and impossible to avoid.","link":"https://gringlizce.com/kelime"},{"tr":"\"plausible\" — kanıtı olmasa da akla yatkın, inandırıcı.","en":"\"plausible\" — believable and reasonable, even without proof.","link":"https://gringlizce.com/kelime"},{"tr":"\"arbitrary\" — mantığa değil keyfe dayalı. \"an arbitrary choice\".","en":"\"arbitrary\" — based on whim rather than reason.","link":"https://gringlizce.com/kelime"},{"tr":"\"coherent\" — parçaları mantıkla bağlanan; her sınav yazısının puan sözcüğü.","en":"\"coherent\" — logically connected throughout; a scoring quality in every exam essay.","link":"https://gringlizce.com/kelime"},{"tr":"\"ambiguous\" — birden çok anlama açık, belirsiz. Sınavda tehlikeli, edebiyatta değerli.","en":"\"ambiguous\" — open to more than one meaning: risky in exams, prized in literature.","link":"https://gringlizce.com/kelime"},{"tr":"\"redundant\" — gereksiz yere tekrar eden. İyi düzeltme, fazlalığı keser.","en":"\"redundant\" — needlessly repetitive; good editing cuts it.","link":"https://gringlizce.com/kelime"},{"tr":"\"prevalent\" — yaygın, baskın. \"a prevalent misconception\".","en":"\"prevalent\" — widespread and dominant: \"a prevalent misconception.\"","link":"https://gringlizce.com/kelime"},{"tr":"\"synthesize\" — dağınık parçaları tek bir bütünde birleştirmek. Command of Evidence''ın özü.","en":"\"synthesize\" — to combine scattered parts into one whole; the core of Command of Evidence.","link":"https://gringlizce.com/sat-soru-bankasi"},{"tr":"\"fewer\" sayılabilenler için, \"less\" sayılamayanlar için: \"fewer cars, less traffic\".","en":"\"fewer\" for countables, \"less\" for uncountables: \"fewer cars, less traffic.\"","link":"https://gringlizce.com/gramer-countable-uncountable"},{"tr":"\"its\" iyeliktir, \"it''s\" ise \"it is\"tir; kesme işareti sahiplik değil kısaltma demektir.","en":"\"its\" shows possession, \"it''s\" means \"it is\" — the apostrophe marks a contraction, not ownership.","link":"https://gringlizce.com/gramer-articles"},{"tr":"\"who\" özne, \"whom\" nesnedir: \"Who called?\" ama \"To whom did you speak?\".","en":"\"who\" is the subject, \"whom\" the object: \"Who called?\" but \"To whom did you speak?\"","link":"https://gringlizce.com/gramer-linking-words"},{"tr":"\"imply\" konuşan ima eder, \"infer\" dinleyen çıkarım yapar; ikisi zıt uçlardadır.","en":"The speaker \"implies,\" the listener \"infers\" — they sit at opposite ends.","link":"https://gringlizce.com/kelime"},{"tr":"\"e.g.\" örnek verir, \"i.e.\" açıklar; ilki \"for example\", ikincisi \"that is\".","en":"\"e.g.\" gives an example, \"i.e.\" restates: one is \"for example,\" the other \"that is.\"","link":"https://gringlizce.com/akademik-citation-reporting-verbs"},{"tr":"İlerleme hız değil süreklilik ödüllendirir; bugünkü küçük adım yarının eksiğini kapatır.","en":"Progress rewards consistency, not speed — today''s small step closes tomorrow''s gap.","link":"https://gringlizce.com/ogrenme-haritasi"},{"tr":"Zor sorular seni değil, hazırlığını sınar. Yanlış, bir sonraki doğrunun haritasıdır.","en":"Hard questions test your prep, not your worth — a wrong answer maps the next right one.","link":"https://gringlizce.com/soru-bankasi"},{"tr":"Bugün çözmediğin soru, sınavda karşına çıkacak boşluktur. Küçük ama düzenli ilerle.","en":"The question you skip today is the gap you meet on exam day — move steadily.","link":"https://gringlizce.com/soru-bankasi"},{"tr":"Hedefini yaz, yolu böl, her gün bir parça al; büyük sonuç küçük günlerin toplamıdır.","en":"Write the goal, split the path, take one piece daily — big results are the sum of small days.","link":"https://gringlizce.com/ogrenme-haritasi"},{"tr":"Bir SAT Reading pasajı bitir ve yalnızca yanlışlarını gerekçesiyle not al.","en":"Finish one SAT Reading passage and log only your wrong answers with reasons.","link":"https://gringlizce.com/sat-soru-bankasi"},{"tr":"Beş yeni sözcüğü bugün kendi cümlelerinde kullan; bağlam, ezberden güçlüdür.","en":"Use five new words in your own sentences today — context beats memorization.","link":"https://gringlizce.com/kelime"},{"tr":"Bir IELTS Task 1''i 20 dakikada yaz, sonra kelime tekrarlarını işaretle.","en":"Write one IELTS Task 1 in 20 minutes, then mark your repeated words.","link":"https://gringlizce.com/yazi-pratigi"},{"tr":"Bir gramer konusunu bitir ve aynı konudan on soru çöz; köprüyü hemen kur.","en":"Finish one grammar topic and solve ten questions on it — build the bridge at once.","link":"https://gringlizce.com/konu-anlatimi"}]}'::jsonb, now()) on conflict (key) do update set value = excluded.value, updated_at = now();